('csdc_vertraege_010',3,'Leistungsbeschreibung und Leistungskatalog','vertraege','client','create','draft','{"key":"csdc_vertraege_010","categoryKey":"vertraege","categoryName":"Verträge und Leistungsvereinbarungen","title":"Leistungsbeschreibung und Leistungskatalog","version":3,"edition":"2027","modules":["office","assist","pflege","stationaer"],"target":"client","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Klient:in / Patient:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"birthDate","label":"Geburtsdatum","type":"date","required":false,"sourcePath":"subject.birthDate"},{"key":"careLevel","label":"Pflegegrad","type":"text","required":false,"sourcePath":"subject.careLevel"},{"key":"payorName","label":"Kostenträger","type":"text","required":false,"sourcePath":"payor.name"},{"key":"insuranceNumber","label":"Versichertennummer","type":"text","required":false,"sourcePath":"subject.insuranceNumber"},{"key":"f0_vereinbarter_leistungsumfang_und_grenzen","label":"Vereinbarter Leistungsumfang und Grenzen","type":"multiline","required":true},{"key":"f1_beginn_laufzeit_und_durchfuehrung","label":"Beginn, Laufzeit und Durchführung","type":"multiline","required":true},{"key":"f2_verguetung_eigenanteile_und_abrechnungsverfahren","label":"Vergütung, Eigenanteile und Abrechnungsverfahren","type":"multiline","required":true},{"key":"f3_laufzeit_absagen_und_kuendigungsbedingungen","label":"Laufzeit, Absagen und Kündigungsbedingungen","type":"multiline","required":true},{"key":"f4_anlagen_und_besondere_vereinbarungen","label":"Anlagen und besondere Vereinbarungen","type":"multiline","required":true},{"key":"legal_contact","label":"Erreichbarer Unternehmenskontakt für Rückfragen und Erklärungen","type":"multiline","required":true},{"key":"legal_signer","label":"Erklärende Person, Eigenerklärung oder Vertretung; bei Vertretung Art, Umfang und Nachweis","type":"multiline","required":true},{"key":"legal_scope","label":"Konkrete Leistungen, Mengen, Grenzen, Beginn, Ort und Zeitraum","type":"multiline","required":true},{"key":"legal_costs","label":"Endpreise je Einheit, Steuern oder Befreiung, voraussichtliche Kosten, Kostenträger und Eigenanteile; keine weiteren Kosten ausdrücklich angeben","type":"multiline","required":true},{"key":"legal_annexes","label":"Einbezogene Anlagen mit Titel, Fassung und Aushändigungsdatum; bei Nachtrag Bezug zur bisherigen Fassung","type":"multiline","required":true},{"key":"legal_conclusion","label":"Art des Vertragsschlusses und ausgehändigte Widerrufsbelehrung; gegebenenfalls gesonderter Wunsch nach vorzeitigem Beginn","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":false,"clinicalReviewRequired":false,"sections":[{"key":"legal_edition","heading":"Ausgabe 2027 · vorbereitet","text":"Bearbeitungsstand: 21.10.2026. Maßgeblich sind die konkret ausgefüllte Fassung, die bezeichneten Anlagen und das zum Leistungszeitpunkt geltende Recht. Künftige Gesetzesentwürfe werden nicht als bereits geltende Regelung vorausgesetzt. Jede beteiligte Person erhält eine vollständige Kopie. Eine vorgegebene Auswahl, ein Portalzugang oder eine Geräteberechtigung ersetzt keine freiwillige Erklärung."},{"key":"legal_scope","heading":"Leistungen, Preise und tatsächliche Durchführung","text":"Verbindlich sind ausschließlich die konkret vereinbarten Leistungen und die ausgewiesenen Endpreise. Art, Menge, Abrechnungseinheit, weitere Kosten und voraussichtlicher Eigenanteil werden vor der Entscheidung erklärt. Eine Kassenleistung setzt die jeweilige Berechtigung und gegebenenfalls Bewilligung voraus. Private Zusatzleistungen benötigen eine ausdrückliche Beauftragung. Nachweise dürfen ausschließlich tatsächlich erbrachte Leistungen bestätigen. Auslagen benötigen Belege und eine vorherige Vereinbarung."},{"key":"legal_changes","heading":"Änderungen, Absagen und Haftung","text":"Wesentliche Änderungen einschließlich ihrer Kostenfolgen werden vorab erläutert und dokumentiert. Eine Absage allein begründet keine pauschale Vergütung. Eine gesonderte zulässige Ausfallregelung berücksichtigt ersparte Aufwendungen und anderweitige Verwendung; der Nachweis eines geringeren oder fehlenden Schadens bleibt möglich. Die Haftung richtet sich nach dem Gesetz. Individuelle Abreden und zwingende Schutzvorschriften bleiben wirksam."},{"key":"legal_withdrawal","heading":"Widerruf und getrennte Erklärungen","text":"Ein gegebenenfalls bestehendes gesetzliches Widerrufsrecht bei Fernabsatz oder Abschluss außerhalb von Geschäftsräumen wird mit vollständiger Belehrung und Musterformular erläutert. Ein vorzeitiger Leistungsbeginn, Wertersatz und das Erlöschen des Widerrufsrechts dürfen nicht allein aus der Vertragsunterschrift abgeleitet werden. Bei einem Verbraucherabschluss über eine Online-Benutzeroberfläche werden die einschlägigen Anforderungen an eine elektronische Widerrufsfunktion gesondert erfüllt."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
